-- A 4-way round-robin arbiter. The requester after the last winner has
-- the highest priority: rotate the requests, pick the first, rotate back.
xblue module mkArbiter;
  input Bool reset;
  input Bit#(4) req;
  Reg#(Bit#(2)) last <- mkReg(3);

  Bit#(2) start   = last + 1;
  Bit#(8) twice   = {req, req};
  Bit#(8) rotated = twice >> start;
  Bit#(4) rot     = rotated[3:0];

  -- first requester at or after `start`, as an offset from it
  Bit#(2) off = priority case
    rot[0] == 1 : 0;
    rot[1] == 1 : 1;
    rot[2] == 1 : 2;
    default : 3;
  endcase;
  Bit#(2) winner = start + off;
  Bool any = req != 0;

  method Bool    io_valid = any;
  method Bit#(2) io_index = winner;
  method Bit#(4) io_grant = any ? 4'b0001 << winner : 0;

  rule advance (any);
    last <= winner;
  endrule

  rule clear (reset);
    last <= 3;
  endrule

  schedule advance ≫ clear;
endmodule
-- ---------------------------------------------------------------- reasoning
open XBlue

/-- One clock cycle of the design itself: the grant it shows, and the next `last`. -/
def next (reset : BitVec 1) (req : BitVec 4) (last : BitVec 2) : BitVec 4 × BitVec 2 :=
  let s := mkArbiter.design.cycle (.cons reset (.cons req .nil)) (.cons last .nil)
  (s.wires.get mkArbiter.io_grant, s.regs.get mkArbiter.last)

/-- The first requester at or after `last + 1`, walking round once. -/
def pick (req : BitVec 4) (last : BitVec 2) : BitVec 2 :=
  if req.getLsbD (last + 1#2).toNat then last + 1#2
  else if req.getLsbD (last + 2#2).toNat then last + 2#2
  else if req.getLsbD (last + 3#2).toNat then last + 3#2
  else last

-- One plain function per step of the cycle.
def grantStep (req : BitVec 4) (last : BitVec 2) : BitVec 4 :=       -- interfaces
  if req = 0#4 then 0#4 else 1#4 <<< (pick req last).toNat
def advanceStep (req : BitVec 4) (last : BitVec 2) : BitVec 2 :=      -- advance
  if req = 0#4 then last else pick req last
def clearStep (reset : BitVec 1) (last : BitVec 2) : BitVec 2 :=      -- clear
  if reset = 1#1 then 3#2 else last

/-- The cycle: show the grant, then advance, then clear. -/
theorem next_eq_steps (reset : BitVec 1) (req : BitVec 4) (last : BitVec 2) :
    next reset req last = (grantStep req last, clearStep reset (advanceStep req last)) := by
  -- unfold the design's cycle
  simp [next, mkArbiter.design, Design.cycle, mkArbiter.schedule, mkArbiter.interfaces,
    mkArbiter.rules.advance, mkArbiter.rules.clear, mkArbiter.values.start, mkArbiter.values.twice,
    mkArbiter.values.rotated, mkArbiter.values.rot, mkArbiter.values.off, mkArbiter.values.winner,
    mkArbiter.values.any, mkArbiter.signature, Sched.run, Action.step, Action.fires, writesIf,
    State.write, State.cur, State.read, HList.set, HList.get, Expr.eval, Expr.binVal, Expr.cmpVal,
    Common.putR, Common.putW, Common.memAt, mkArbiter.last, mkArbiter.reset, mkArbiter.req,
    mkArbiter.io_grant, mkArbiter.io_valid, mkArbiter.io_index, sliceWidth]
  -- name the three steps
  simp only [grantStep, advanceStep, clearStep, pick]
  revert reset req last
  decide

/-- The grant is at most one requester. -/
theorem grant_is_one_hot (reset : BitVec 1) (req : BitVec 4) (last : BitVec 2) :
    (next reset req last).1 ∈ [0#4, 1#4, 2#4, 4#4, 8#4] := by
  rw [next_eq_steps]
  simp only [grantStep, pick]
  revert req last
  decide

/-- The last winner goes to the back of the line: if anyone else asks, it does not win again. -/
theorem last_winner_yields (req : BitVec 4) (last : BitVec 2)
    (other : req &&& ~~~(1#4 <<< last.toNat) ≠ 0#4) :
    (next 0#1 req last).2 ≠ last := by
  rw [next_eq_steps]
  simp only [clearStep, advanceStep, pick]
  revert req last
  decide

