-- A 4-way round-robin arbiter. The requester after the last winner has
-- the highest priority: rotate the requests, pick the first, rotate back.
xblue module mkArbiter;
  input Bool reset;
  input Bit#(4) req;
  Reg#(Bit#(2)) last <- mkReg(3);

  Bit#(2) start   = 0;
  Bit#(8) twice   = {req, req};
  Bit#(8) rotated = twice >> start;
  Bit#(4) rot     = rotated[3:0];

  -- first requester at or after `start`, as an offset from it
  Bit#(2) off = priority case
    rot[0] == 1 : 0;
    rot[1] == 1 : 1;
    rot[2] == 1 : 2;
    default : 3;
  endcase;
  Bit#(2) winner = start + off;
  Bool any = req != 0;

  method Bool    io_valid = any;
  method Bit#(2) io_index = winner;
  method Bit#(4) io_grant = any ? 4'b0001 << winner : 0;

  rule advance (any);
    last <= winner;
  endrule

  rule clear (reset);
    last <= 3;
  endrule

  schedule advance ≫ clear;
endmodule
